                        $"https://{parsedArnSsa2!.AccountId}.ddb.{region!}.{partitionResult!.DnsSuffix}"
                    ),
                    AuthSchemes: DefaultAuthSchemes(),
                    Properties: new Dictionary<string, Document>
                    {
                        ["metricValues"] = Document.From(new Document[] { Document.From("O") }),
                    }
                ),
                31 => new SmithyEndpoint(
                    new Uri(
                        $"https://{parsedArnSsa1!.AccountId}.search-ddb.{region!}.{partitionResult!.DnsSuffix}"
                    ),
                    AuthSchemes: DefaultAuthSchemes(),
                    Properties: new Dictionary<string, Document>
                    {
                        ["metricValues"] = Document.From(new Document[] { Document.From("O") }),
                    }
                ),
                32 => new SmithyEndpoint(
                    new Uri(
                        $"https://{parsedArnSsa1!.AccountId}.ddb.{region!}.{partitionResult!.DnsSuffix}"
                    ),
                    AuthSchemes: DefaultAuthSchemes(),
                    Properties: new Dictionary<string, Document>
                    {
                        ["metricValues"] = Document.From(new Document[] { Document.From("O") }),
                    }
                ),
                33 => new SmithyEndpoint(
                    new Uri(
                        $"https://{accountId!}.search-ddb.{region!}.{partitionResult!.DnsSuffix}"
                    ),
                    AuthSchemes: DefaultAuthSchemes(),
                    Properties: new Dictionary<string, Document>
                    {
                        ["metricValues"] = Document.From(new Document[] { Document.From("O") }),
                    }
                ),
                34 => new SmithyEndpoint(
                    new Uri($"https://{accountId!}.ddb.{region!}.{partitionResult!.DnsSuffix}"),
                    AuthSchemes: DefaultAuthSchemes(),
                    Properties: new Dictionary<string, Document>
                    {
                        ["metricValues"] = Document.From(new Document[] { Document.From("O") }),
                    }
                ),
                35 => throw new SmithyEndpointResolutionException(
                    "Invalid Configuration: Missing Region"
                ),
                _ => throw SmithyEndpointResolutionException.NoMatch(),
            };

        IReadOnlyList<SmithyEndpointAuthScheme> DefaultAuthSchemes() =>
            new SmithyEndpointAuthScheme[]
            {
                new SmithyEndpointAuthScheme(
                    "aws.auth#sigv4",
                    new Dictionary<string, Document>
                    {
                        ["signingName"] = Document.From("dynamodb"),
                        ["signingRegion"] = region is null ? Document.Null : Document.From(region),
                    }
                ),
            };
    }

    private static bool IsNode(int reference) =>
        reference is > 1 and < ResultOffset or < -1 and > -ResultOffset;
}
